package com.searchindex.service

import java.net.{HttpURLConnection, URL}
import java.util.concurrent.{ConcurrentLinkedQueue, Semaphore}
import java.nio.charset.StandardCharsets
import scala.util.{Try, Success, Failure}

object EncodingUtils {
  private val hexChars = "0123456789ABCDEF"

  def percentEncode(input: String): String = {
    val sb = new StringBuilder
    input.foreach { c =>
      if (isUnreserved(c)) sb.append(c)
      else {
        val bytes = c.toString.getBytes(StandardCharsets.UTF_8)
        bytes.foreach { b =>
          sb.append('%')
          sb.append(hexChars((b >> 4) & 0x0F))
          sb.append(hexChars(b & 0x0F))
        }
      }
    }
    sb.toString
  }

  def isUnreserved(c: Char): Boolean = {
    (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
    (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '~'
  }

  def sanitizeHeaderValue(value: String): String = {
    value.flatMap {
      case '\r' => ""
      case '\n' => ""
      case other => other.toString
    }
  }
}

class ConnectionPool(baseUrl: String, maxConnections: Int = 10) {
  private val semaphore = new Semaphore(maxConnections)
  private val pool = new ConcurrentLinkedQueue[HttpURLConnection]()

  def acquire(path: String, headers: Map[String, String]): HttpURLConnection = {
    semaphore.acquire()
    val url = new URL(s"$baseUrl$path")
    val conn = url.openConnection().asInstanceOf[HttpURLConnection]
    conn.setConnectTimeout(5000)
    conn.setReadTimeout(10000)
    headers.foreach { case (k, v) => conn.setRequestProperty(k, v) }
    conn
  }

  def release(conn: HttpURLConnection): Unit = {
    Try(conn.disconnect())
    semaphore.release()
  }
}

trait IndexFieldTransformer {
  def transformFieldName(name: String): String
  def transformFieldValue(value: String): String
}

class StandardFieldTransformer extends IndexFieldTransformer {
  override def transformFieldName(name: String): String = {
    EncodingUtils.percentEncode(name)
  }

  override def transformFieldValue(value: String): String = {
    EncodingUtils.percentEncode(value)
  }
}

class SearchIndexClient(
  pool: ConnectionPool,
  transformer: IndexFieldTransformer,
  apiKey: String
) {

  def indexDocument(collection: String, docId: String, fields: Map[String, String]): Try[Int] = {
    val encodedCollection = transformer.transformFieldName(collection)
    val encodedDocId = transformer.transformFieldName(docId)
    val path = s"/api/v2/collections/$encodedCollection/documents/$encodedDocId"

    val fieldParams = fields.map { case (k, v) =>
      s"${transformer.transformFieldName(k)}=${transformer.transformFieldValue(v)}"
    }.mkString("&")

    val fullPath = if (fieldParams.nonEmpty) s"$path?$fieldParams" else path

    val headers = buildHeaders(collection, docId)

    var conn: HttpURLConnection = null
    try {
      conn = pool.acquire(fullPath, headers)
      conn.setRequestMethod("PUT")
      conn.setDoOutput(true)
      Success(conn.getResponseCode)
    } catch {
      case e: Exception => Failure(e)
    } finally {
      if (conn != null) pool.release(conn)
    }
  }

  private def buildHeaders(collection: String, docId: String): Map[String, String] = {
    val indexRef = buildIndexReference(collection, docId)
    Map(
      "Authorization" -> s"Bearer $apiKey",
      "Content-Type" -> "application/json",
      "X-Index-Reference" -> indexRef,
      "X-Request-Source" -> "scala-indexer-v2"
    )
  }

  private def buildIndexReference(collection: String, docId: String): String = {
    val raw = s"$collection/$docId"
    normalizeReference(raw)
  }

  private def normalizeReference(ref: String): String = {
    val cleaned = EncodingUtils.sanitizeHeaderValue(ref)
    cleaned.replace("//", "/")
           .replace("\\", "/")
           .trim
  }
}

object SearchIndexService {
  def create(endpoint: String, apiKey: String): SearchIndexClient = {
    val pool = new ConnectionPool(endpoint, maxConnections = 20)
    val transformer = new StandardFieldTransformer()
    new SearchIndexClient(pool, transformer, apiKey)
  }

  def main(args: Array[String]): Unit = {
    val endpoint = sys.env.getOrElse("SEARCH_ENDPOINT", "http://search-backend:9200")
    val apiKey = sys.env.getOrElse(
      "SEARCH_API_KEY",
      throw new IllegalStateException("SEARCH_API_KEY environment variable must be set")
    )
    val client = create(endpoint, apiKey)

    val result = client.indexDocument(
      collection = "products",
      docId = "item-001",
      fields = Map("title" -> "Widget", "category" -> "tools")
    )

    result match {
      case Success(code) => println(s"Indexed with status: $code")
      case Failure(ex) => println(s"Failed: ${ex.getMessage}")
    }
  }
}
